onto = {
    'dog': [('mammal', 'IS-A', 0.8)],
    'mammal': [('dog', 'HAS', 0.7), ('cat', 'HAS', 0.7)],
}

def expand(term, depth=1, decay=0.8):
    out, frontier = {term: 1.0}, [(term, 1.0, 0)]
    while frontier:
        t, w, d = frontier.pop()
        if d < depth:
            for rel, kind, rw in onto.get(t, []):
                nw = w * rw * decay
                if rel not in out or out[rel] < nw:
                    out[rel] = nw
                    frontier.append((rel, nw, d + 1))
    return out

print('query "dog" expands to:', expand('dog'))
