senses = {
    'phone': [(1900, 2000, 'wall-mounted voice device'), (2000, 2030, 'mobile computer')],
}

def sense_at(word, year):
    return next(s for f, t, s in senses[word] if f <= year < t)

print('phone in 1985:', sense_at('phone', 1985))
print('phone in 2020:', sense_at('phone', 2020))
