versions = {
    '1.0': {'phone': 'device'},
    '2.0': {'phone': 'DEPRECATED: use mobile_phone', 'mobile_phone': 'device'},
}
migration = {'1.0->2.0': {'phone': 'mobile_phone'}}

def lookup(word, ver):
    entry = versions[ver].get(word, 'unknown')
    if entry.startswith('DEPRECATED'):
        new = migration['1.0->2.0'][word]
        return '%s -> migrated to %s' % (entry, new)
    return entry

print('v1.0 phone:', lookup('phone', '1.0'))
print('v2.0 phone:', lookup('phone', '2.0'))
