# transitive closure: derive what was never stated
isa = {('dog', 'mammal'), ('mammal', 'animal'), ('cat', 'mammal')}

def closure(pairs):
    c = set(pairs)
    changed = True
    while changed:
        changed = False
        for a, b in list(c):
            for x, y in list(c):
                if b == x and (a, y) not in c:
                    c.add((a, y))
                    changed = True
    return c

closed = closure(isa)
print('stated:', sorted(isa))
print('derived:', sorted(closed - isa), '(never written, always true)')
print('materialize at build: queries read the closed graph, fast')

